53: /** Obstacle volumes only ever rotate around Y, so the quaternion collapses to a yaw. */
54: function yawOf(rotation: Quat | undefined): number {
55:   if (!rotation) return 0;
56:   const { x, y, z, w } = rotation;
57:   return Math.atan2(2 * (w * y + x * z), 1 - 2 * (y * y + z * z));
58: }
