60: function halfExtentsOf(obstacle: ObstacleDescriptor): Vec3 {
61:   const scale = obstacle.transform.scale;
62:   return {
63:     x: Math.abs(obstacle.size.x * (scale?.x ?? 1)) / 2,
64:     y: Math.abs(obstacle.size.y * (scale?.y ?? 1)) / 2,
65:     z: Math.abs(obstacle.size.z * (scale?.z ?? 1)) / 2,
66:   };
67: }
