69: /** Oriented box the force obstacles and pads test the ball against. */
70: export function descriptorZone(obstacle: ObstacleDescriptor): BoxZone {
71:   return {
72:     shape: 'box',
73:     center: { ...obstacle.transform.position },
74:     halfExtents: halfExtentsOf(obstacle),
75:     rotationY: yawOf(obstacle.transform.rotation),
76:   };
77: }
