79: /** Axis aligned bounds used by the gameplay zones, which never rotate. */
80: export function descriptorBounds(obstacle: ObstacleDescriptor): ZoneBounds {
81:   const center = obstacle.transform.position;
82:   const half = halfExtentsOf(obstacle);
83:   return {
84:     min: { x: center.x - half.x, y: center.y - half.y, z: center.z - half.z },
85:     max: { x: center.x + half.x, y: center.y + half.y, z: center.z + half.z },
86:   };
87: }
