93: export function isPadDescriptor(obstacle: ObstacleDescriptor): obstacle is PadDescriptor {
94:   return obstacle.type === 'spring-pad' || obstacle.type === 'boost-pad' || obstacle.type === 'jump-pad';
95: }
96: 
97: export function isFieldObstacle(obstacle: ObstacleDescriptor): obstacle is FieldObstacle {
98:   return obstacle.type === 'gravity-zone' || obstacle.type === 'magnet-zone';
99: }
