101: export function isHazardObstacle(obstacle: ObstacleDescriptor): obstacle is HazardObstacle {
102:   return (
103:     obstacle.type === 'water' ||
104:     obstacle.type === 'void' ||
105:     obstacle.type === 'reset-zone' ||
106:     obstacle.type === 'lava'
107:   );
108: }
