114: export function createForceObstacle(descriptor: ForceObstacle): BallObstacle {
115:   const zone = descriptorZone(descriptor);
116:   if (descriptor.type === 'teleporter') {
117:     return new TeleporterObstacle({
118:       id: descriptor.id,
119:       kind: 'teleporter',
120:       enabled: descriptor.enabled,
121:       entryZone: zone,
122:       exitPosition: { ...descriptor.exit },
123:       exitVelocityScale: descriptor.exitVelocityScale,
124:       clearAngularVelocity: descriptor.clearAngularVelocity,
125:     });
126:   }
127: 
128:   const direction = normalizeVec3(descriptor.direction) ?? FORWARD;
129:   if (descriptor.type === 'fan') {
130:     return new FanObstacle({
131:       id: descriptor.id,
132:       kind: 'fan',
133:       enabled: descriptor.enabled,
134:       zone,
135:       direction,
136:       maxForce: descriptor.strength,
137:       falloff: descriptor.falloff,
138:       pulse: descriptor.pulse,
139:     });
140:   }
141: 
142:   return new ConveyorObstacle({
143:     id: descriptor.id,
144:     kind: 'conveyor',
145:     enabled: descriptor.enabled,
146:     zone,
147:     direction,
148:     targetSpeed: descriptor.strength,
149:     coupling: descriptor.coupling,
150:   });
151: }
