153: export function createPad(descriptor: PadDescriptor): PadObstacle {
154:   return new PadObstacle({
155:     id: descriptor.id,
156:     kind: PAD_KINDS[descriptor.type],
157:     zone: descriptorZone(descriptor),
158:     strength: descriptor.strength,
159:     direction: descriptor.direction,
160:     maxSpeed: descriptor.maxSpeed,
161:     cooldownSeconds: descriptor.cooldownSeconds,
162:     enabled: descriptor.enabled,
163:   });
164: }
