166: /** Static bumpers double as impulse pads; their restitution drives the bounce strength. */
167: export function createBumperPad(descriptor: StaticObstacle): PadObstacle | null {
168:   if (descriptor.type !== 'bumper') return null;
169:   return new PadObstacle({
170:     id: descriptor.id,
171:     kind: 'bumper',
172:     zone: descriptorZone(descriptor),
173:     strength: descriptor.restitution ?? 1,
174:     enabled: descriptor.enabled,
175:   });
176: }
