178: export function createZone(descriptor: FieldObstacle | HazardObstacle): IZone {
179:   const bounds = descriptorBounds(descriptor);
180:   switch (descriptor.type) {
181:     case 'water':
182:       return new WaterZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 1, descriptor.resetPosition);
183:     case 'lava':
184:       return new LavaZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 2, descriptor.resetPosition);
185:     case 'void':
186:     case 'reset-zone':
187:       return new KillZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 1, descriptor.resetPosition);
188:     case 'gravity-zone':
189:       return new GravityZone(descriptor.id, bounds, descriptor.strength, descriptor.direction ?? DOWN);
190:     case 'magnet-zone':
191:       return new MagnetZone(descriptor.id, bounds, descriptor.strength, descriptor.repel ?? false);
192:   }
193: }
