195: export function createRotatingConfig(descriptor: MovingObstacle): RotatingConfig | null {
196:   const kind = ROTATING_KINDS[descriptor.type];
197:   if (!kind || descriptor.motion.kind === 'translate') return null;
198:   const motion = descriptor.motion;
199:   return {
200:     id: descriptor.id,
201:     kind,
202:     center: { ...descriptor.transform.position },
203:     armLength: motion.armLength ?? Math.max(descriptor.size.x, descriptor.size.z) / 2,
204:     speed: motion.speed,
205:     phase: motion.phase,
206:     clockwise: motion.clockwise,
207:     swingAngle: motion.swingAngle,
208:     enabled: descriptor.enabled,
209:   };
210: }
211: 
212: export function createMoverConfig(descriptor: MovingObstacle): MoverConfig | null {
213:   const kind = MOVER_KINDS[descriptor.type];
214:   if (!kind || descriptor.motion.kind !== 'translate') return null;
215:   const motion = descriptor.motion;
216:   return {
217:     id: descriptor.id,
218:     kind,
219:     origin: { ...descriptor.transform.position },
220:     axis: { ...motion.axis },
221:     distance: motion.distance ?? 0,
222:     speed: Math.abs(motion.speed),
223:     phase: motion.phase,
224:     loop: motion.loop,
225:     pauseSeconds: motion.pauseSeconds,
226:     enabled: descriptor.enabled,
227:   };
228: }
