238: /** Instantiates every runtime helper a hole descriptor asks for, grouped by system. */
239: export function buildHoleObstacleRuntime(hole: Hole): HoleObstacleRuntime {
240:   const runtime: HoleObstacleRuntime = { forces: [], pads: [], zones: [], rotating: [], movers: [] };
241: 
242:   for (const obstacle of hole.obstacles) {
243:     if (isForceObstacle(obstacle)) {
244:       runtime.forces.push(createForceObstacle(obstacle));
245:     } else if (isPadDescriptor(obstacle)) {
246:       runtime.pads.push(createPad(obstacle));
247:     } else if (isFieldObstacle(obstacle) || isHazardObstacle(obstacle)) {
248:       runtime.zones.push(createZone(obstacle));
249:     } else if (isMovingObstacle(obstacle)) {
250:       const rotating = createRotatingConfig(obstacle);
251:       if (rotating) runtime.rotating.push(rotating);
252:       const mover = createMoverConfig(obstacle);
253:       if (mover) runtime.movers.push(mover);
254:     } else {
255:       const bumper = createBumperPad(obstacle);
256:       if (bumper) runtime.pads.push(bumper);
257:     }
258:   }
259: 
260:   return runtime;
261: }
